arguments.command:
cd /tmp/vally-eval-trial-2McQML && mkdir -p tests/CheckoutPricing.UnitTests/Checkout &&
cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Gold
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalCommand(CustomerTier Tier, decimal Subtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalCommand command) => command.Subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var handler = new CalculatePayableTotalHandler();

        var total = handler.Handle(new CalculatePayableTotalCommand(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~LoyaltyDiscountTests" --verbosity quiet 2>&1 | tail -20

